# Generate K_{6,6} as a maximal triangle-free graph
edges = []
for u in range(6):
    for v in range(6, 12):
        edges.append((u, v))

print(f"Number of edges: {len(edges)}")
print("Edges:", edges)

# Verify it's triangle-free
def is_triangle_free(edges, n):
    adj = {i: set() for i in range(n)}
    for u, v in edges:
        adj[u].add(v)
        adj[v].add(u)

    for i in range(n):
        for j in adj[i]:
            if j > i:
                for k in adj[j]:
                    if k > j and k in adj[i]:
                        return False, (i, j, k)
    return True, None

triangle_free, triangle = is_triangle_free(edges, 12)
print(f"Triangle-free: {triangle_free}")
if not triangle_free:
    print(f"Triangle found: {triangle}")

# Verify it's maximal (adding any missing edge creates a triangle)
def is_maximal_triangle_free(edges, n):
    adj = {i: set() for i in range(n)}
    for u, v in edges:
        adj[u].add(v)
        adj[v].add(u)

    # Check all non-edges
    for i in range(n):
        for j in range(i+1, n):
            if j not in adj[i]:
                # Try adding edge (i, j)
                # Check if this creates a triangle
                creates_triangle = False
                for k in range(n):
                    if k != i and k != j:
                        if k in adj[i] and k in adj[j]:
                            creates_triangle = True
                            break
                if not creates_triangle:
                    return False, (i, j)
    return True, None

maximal, non_maximal_edge = is_maximal_triangle_free(edges, 12)
print(f"Maximal: {maximal}")
if not maximal:
    print(f"Can add edge without creating triangle: {non_maximal_edge}")
